/**
 * Unit tests for JacksonAnnotationIntrospector.findContentDeserializer
 */
public class JacksonAnnotationIntrospector_findContentDeserializer_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;
    private Annotated annotatedMock;

    // A dummy deserializer class for testing
    public static class DummyDeserializer extends StdDeserializer<Object> {
        protected DummyDeserializer() {
            super(Object.class);
        }

        @Override
        public Object deserialize(JsonParser p, com.fasterxml.jackson.databind.DeserializationContext ctxt) throws IOException {
            return null;
        }
    }

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        annotatedMock = Mockito.mock(Annotated.class);
    }

    /**
     * Test Case 1: The annotation JsonDeserialize is not present on the Annotated object.
     * Expected: Returns null.
     */
    @Test
    public void testFindContentDeserializer_NoAnnotation() {
        // Mock _findAnnotation behavior (which is called internally via the logic)
        // Since _findAnnotation is a protected method of the class being tested, 
        // we rely on the fact that Mockito cannot easily mock the internal call unless we spy.
        // However, JacksonAnnotationIntrospector uses the Annotated object to find annotations.

        // In Jackson's implementation, _findAnnotation calls annotated.getAnnotation(annotationClass)
        when(annotatedMock.getAnnotation(JsonDeserialize.class)).thenReturn(null);

        Object result = introspector.findContentDeserializer(annotatedMock);

        assertNull("Should return null when no JsonDeserialize annotation is found", result);
    }

    /**
     * Test Case 2: The annotation JsonDeserialize is present, but contentUsing() returns JsonDeserializer.None.class.
     * Expected: Returns null.
     */
    @Test
    public void testFindContentDeserializer_WithNoneDeserializer() {
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);
        when(annotatedMock.getAnnotation(JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(JsonDeserializer.None.class);

        Object result = introspector.findContentDeserializer(annotatedMock);

        assertNull("Should return null when contentUsing is JsonDeserializer.None.class", result);
    }

    /**
     * Test Case 3: The annotation JsonDeserialize is present and contentUsing() returns a valid deserializer class.
     * Expected: Returns the deserializer class.
     */
    @Test
    public void testFindContentDeserializer_WithValidDeserializer() {
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);
        when(annotatedMock.getAnnotation(JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(DummyDeserializer.class);

        Object result = introspector.findContentDeserializer(annotatedMock);

        assertEquals("Should return the specific deserializer class", DummyDeserializer.class, result);
    }
}
